import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

const MenuLabel = forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ children, className, ...props }, ref) => {
    const { RadixComponent } = useMenu();
    return (
      <RadixComponent.Label
        ref={ref}
        className={clsx(MenuClasses.groupLabel, className)}
        {...props}
      >
        {children}
      </RadixComponent.Label>
    );
  },
);
MenuLabel.displayName = "Menu.Label";

export { MenuLabel };
